package com.example.erp.config;
import com.example.erp.repo.UserRepo;import org.springframework.context.annotation.*;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.userdetails.User;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig{
@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
@Bean UserDetailsService userDetailsService(UserRepo users){return username->users.findByUsername(username).map(u->User.withUsername(u.username).password(u.password).roles(u.role).build()).orElseThrow(()->new UsernameNotFoundException("User not found"));}
@Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/","/index.html","/css/**","/js/**","/h2-console/**","/swagger-ui/**","/v3/api-docs/**").permitAll().anyRequest().authenticated()).httpBasic(b->{}).headers(x->x.frameOptions(f->f.sameOrigin())).build();}}
